#include <vector>
#include <algorithm>

class Solution {
public:
    int minCostClimbingStairs(std::vector<int>& cost) {
        int n = cost.size();
        if (n <= 1) return 0;

        int dp0 = cost[0], dp1 = cost[1];
        for (int i = 2; i < n; ++i) {
            int curr = cost[i] + std::min(dp0, dp1);
            dp0 = dp1;
            dp1 = curr;
        }
        return std::min(dp0, dp1);
    }
};

class Solution {
    public int minCostClimbingStairs(int[] cost) {
        int n = cost.length;
        if (n <= 1) return 0;

        int dp0 = cost[0], dp1 = cost[1];
        for (int i = 2; i < n; i++) {
            int curr = cost[i] + Math.min(dp0, dp1);
            dp0 = dp1;
            dp1 = curr;
        }
        return Math.min(dp0, dp1);
    }
}

var minCostClimbingStairs = function(cost) {
    const n = cost.length;
    if (n <= 1) return 0;

    let dp0 = cost[0], dp1 = cost[1];
    for (let i = 2; i < n; i++) {
        const curr = cost[i] + Math.min(dp0, dp1);
        dp0 = dp1;
        dp1 = curr;
    }
    return Math.min(dp0, dp1);
